CommitDate: Tue Jun 9 11:28:05 2026 +0200

    Bug 1032360 - Compute local maildir folder size from the message store instead of stat'ing the folder directory. r=BenC


    nsMsgLocalMailFolder::GetSizeOnDisk() called GetFileSize() on the folder's
    file path. For mbox that's the mbox file, but for maildir it's the folder
    directory, so the reported size was the directory inode size (0 on Windows,
    ~4096 on ext4) instead of the total size of the messages.

    Delegate to nsIMsgPluggableStore::estimateFolderSize() instead, which already
    has correct mbox and maildir implementations. Also harden the maildir
    implementation to return 0 when the cur/ subdirectory does not exist yet,
    matching how the mbox store handles a missing mbox file.

    Differential Revision: https://phabricator.services.mozilla.com/D305090

diff --git a/mailnews/local/src/nsLocalMailFolder.cpp b/mailnews/local/src/nsLocalMailFolder.cpp
index 088b4a7f21d..512e166839d 100644
--- a/mailnews/local/src/nsLocalMailFolder.cpp
+++ b/mailnews/local/src/nsLocalMailFolder.cpp
@@ -1055,13 +1055,13 @@ NS_IMETHODIMP nsMsgLocalMailFolder::GetSizeOnDisk(int64_t* aSize) {
   if (folderFlags & nsMsgFolderFlags::Virtual) mFolderSize = 0;

   if (mFolderSize == kSizeUnknown) {
-    nsCOMPtr<nsIFile> file;
-    rv = GetFilePath(getter_AddRefs(file));
+    nsCOMPtr<nsIMsgPluggableStore> msgStore;
+    rv = GetMsgStore(getter_AddRefs(msgStore));
     NS_ENSURE_SUCCESS(rv, rv);
     // Use a temporary variable so that we keep mFolderSize on kSizeUnknown
-    // if GetFileSize() fails.
+    // if EstimateFolderSize() fails.
     int64_t folderSize;
-    rv = file->GetFileSize(&folderSize);
+    rv = msgStore->EstimateFolderSize(this, &folderSize);
     NS_ENSURE_SUCCESS(rv, rv);

     mFolderSize = folderSize;
diff --git a/mailnews/local/src/nsMsgMaildirStore.cpp b/mailnews/local/src/nsMsgMaildirStore.cpp
index 4868efba06e..c6b70cbf3ca 100644
--- a/mailnews/local/src/nsMsgMaildirStore.cpp
+++ b/mailnews/local/src/nsMsgMaildirStore.cpp
@@ -1319,6 +1319,16 @@ NS_IMETHODIMP nsMsgMaildirStore::EstimateFolderSize(nsIMsgFolder* folder,
   NS_ENSURE_SUCCESS(rv, rv);
   cur->Append(u"cur"_ns);

+  // The cur/ subdirectory may not exist yet (e.g. no messages have been
+  // delivered). Treat that as a size of 0, the same way the mbox store
+  // treats a missing mbox file.
+  bool exists = false;
+  rv = cur->Exists(&exists);
+  NS_ENSURE_SUCCESS(rv, rv);
+  if (!exists) {
+    return NS_OK;
+  }
+
   nsCOMPtr<nsIDirectoryEnumerator> dirEnumerator;
   rv = cur->GetDirectoryEntries(getter_AddRefs(dirEnumerator));
   NS_ENSURE_SUCCESS(rv, rv);
